(function(g){'use strict';const C={"slug": "trajectory-control", "title": "井眼轨迹控制：学到转向响应后怎样接近目标", "methods": ["opt"], "question": "相同转向动作在不同地层中响应不同，怎样兼顾目标偏差与弯曲约束？", "concepts": [["测深、垂深与横向位移", "沿井眼量出的长度是测深MD；相对地面的竖直距离是真垂深TVD。斜井的测深通常大于垂深。这里每一步前进10m，再按井斜角分解成横向位移与垂深增量。", "轨迹图纵轴向下增加，因此曲线越向下表示井眼越深。"], ["弯得太急也有代价", "狗腿度描述单位井段内井眼方向改变的幅度，常用°/30m表示。即使目标更近，过大的局部弯曲也会给工具通过和钻柱运动带来困难。本例把它简化为二维转角约束。", "调小约束后，观察轨迹如何更平缓，以及末端误差怎样变化。"], ["智能方法学习的是动作响应", "从独立转向试验拟合“指令转角→实际转角”的增益。用学到的增益比较21个横向补偿候选，再把选中动作应用到用户设定的未来响应。未来增益偏离训练增益时，路径会产生误差。", "学习响应、候选搜索、未来推进是三个独立环节。"]], "steps": [["标定转向响应", "80条转向试验拟合响应增益。", "学习增益与训练样本数", "从独立转向试验拟合增益，再应用于未来推进。"], ["约束内比较候选", "对21个横向目标补偿进行60步前推。", "候选偏差曲线", "每推进10 m，按转角上限筛选动作。"], ["推进并对照基线", "使用未来响应推进选中动作，与单位增益追踪比较。", "实际轨迹、目标偏差、超限数", "末端偏差按用户设定的原始目标计算。"]], "params": [["targetX", "目标横向位移 / m", 30, 350, 10, 180], ["targetZ", "目标真垂深 / m", 450, 600, 5, 550], ["gain", "未来地层转向响应", 0.35, 1.3, 0.05, 0.75], ["limit", "转角上限 / °·30m⁻¹", 2, 12, 0.5, 7]], "sources": [["SLB｜Dogleg", "https://glossary.slb.com/terms/d/dogleg"]], "scene": "d3", "id": "s17x-d3-trajectory-control", "learningExperiment": "保持未来增益0.75，将转角上限由7降到2 °/30m并重算，比较轨迹与末端偏差；再将未来增益改为1.3。训练增益保持不变，执行路径和超限数可能改变。60步MD固定600m，因此部分目标位置不可达。", "workedExamples": [{"title": "先看指令是否等于响应", "headers": ["指令转角 / °", "增益", "响应转角 / °"], "rows": [[1, 0.74, 0.74], [2, 0.74, 1.48], [-2, 0.74, -1.48]], "interpretation": "此表用0.74作手算示意；页面训练面板显示80条试验实际拟合的增益。"}, {"title": "每步分解位移", "headers": ["ΔMD / m", "θ / °", "Δx / m", "ΔTVD / m"], "rows": [[10, 0, 0, 10], [10, 30, 5, 8.66], [10, 60, 8.66, 5]], "interpretation": "输入先转弧度，60步总MD=600m。沿横向比较21个补偿候选，总进尺固定600 m。"}, {"title": "目标与终点比较", "headers": ["目标(x,z) / m", "终点(x,z) / m", "欧氏距离 / m"], "rows": [["(180,550)", "(190,530)", "√(10²+20²)=22.36"]], "interpretation": "候选由学习增益排序；动作确定后按未来增益推进，再以原始目标评分。"}]},E=g.Experiment,$=id=>document.getElementById(id),state={status:'initializing',results:null,params:null,revision:0,reviews:[]};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v==null?'—':typeof v==='number'?(Number.isInteger(v)?v:v.toFixed(3)):v;
function params(){let p={};C.params.forEach(a=>p[a[0]]=Number($(a[0]).value));(C.selects||[]).forEach(a=>p[a[0]]=$(a[0]).value);return p}
function svg(title,b,w=820,h=350){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}">${b}</svg>`}
function depthChart(v){
 const all=v.traces.flatMap(t=>t.values.filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1]))),ds=all.map(p=>p[0]),vs=all.map(p=>p[1]),d0=Math.min(...ds),d1=Math.max(...ds);let a=Math.min(...vs),z=Math.max(...vs),pad=(z-a)*.08||.1;a-=pad;z+=pad;
 const x=n=>90+(n-a)/(z-a)*670,y=n=>55+(n-d0)/(d1-d0||1)*390;let s='<rect x="90" y="55" width="670" height="390" fill="#fafcf9" stroke="#cfddd5"/>';
 if(v.band)s+=`<rect x="90" y="${y(v.band[0])}" width="670" height="${y(v.band[1])-y(v.band[0])}" fill="#e8bc72" opacity=".18"/>`;
 for(let j=0;j<=4;j++){let value=a+(z-a)*j/4,d=d0+(d1-d0)*j/4;s+=`<path d="M${x(value)} 55V445M90 ${y(d)}H760" stroke="#dfe8e1"/><text x="${x(value)}" y="470" text-anchor="middle" font-size="14">${value.toFixed(z-a<10?2:0)}</text><text x="78" y="${y(d)+5}" text-anchor="end" font-size="14">${d.toFixed(1)}</text>`}
 (v.truthMarkers||[]).forEach(d=>s+=`<path d="M90 ${y(d)}H760" stroke="#929ca3" stroke-dasharray="3 5"/>`);(v.markers||[]).forEach(d=>s+=`<path d="M90 ${y(d)}H760" stroke="#c07648" stroke-dasharray="7 4"/>`);
 v.traces.forEach((t,j)=>{let path='',start=false;t.values.forEach(p=>{if(!Number.isFinite(p[1])){start=false;return}path+=(start?'L':'M')+x(p[1])+','+y(p[0]);start=true});s+=`<path d="${path}" stroke="${t.color}" stroke-width="${j===0?3.8:2.4}" ${j>1?'stroke-dasharray="7 4"':''} fill="none"/>`});
 s+=`<text x="90" y="27" font-size="16">${esc(v.xLabel)} ↓</text><text x="420" y="512" text-anchor="middle" font-size="16">${esc(v.yLabel)}</text>`;return svg(v.title,s,820,530)}
function chart(v){if(/^MD \//.test(v.xLabel||''))return depthChart(v);if(v.kind==='image'){let names=['原始响应','灰度基线','局部特征模型','独立真值'],layers=[null,v.baseline,v.mask,v.truth],b='';layers.forEach((layer,j)=>{let x0=16+j*200;b+=`<text x="${x0}" y="22" font-size="16">${names[j]}</text>`;for(let y=0;y<v.h;y++)for(let x=0;x<v.w;x++){let i=y*v.w+x,gray=Math.round(v.pixels[i]*255),color=layer?(layer[i]?'#14796f':'#e9efea'):`rgb(${gray},${gray},${gray})`;b+=`<rect x="${x0+x*1.9}" y="${35+y*2.3}" width="1.95" height="2.35" fill="${color}"/>`}b+=`<text x="${x0}" y="225" font-size="14">0°</text><text x="${x0+145}" y="225" font-size="14">360°</text>`});return svg(v.title,b,820,245)}
let all=v.traces.flatMap(t=>t.values.filter(p=>p[0]!==null&&p[1]!==null&&Number.isFinite(p[0])&&Number.isFinite(p[1]))),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]);let loX=Math.min(...xs),hiX=Math.max(...xs),loY=Math.min(...ys),hiY=Math.max(...ys);if(v.diagonal){let lo=Math.min(loX,loY),hi=Math.max(hiX,hiY);loX=loY=lo;hiX=hiY=hi}let pad=(hiY-loY)*.08||1;loY-=pad;hiY+=pad;let x=a=>75+(a-loX)/(hiX-loX||1)*700,y=a=>v.depth?48+(a-loY)/(hiY-loY||1)*225:273-(a-loY)/(hiY-loY||1)*225;
let b=`<rect x="75" y="48" width="700" height="225" fill="#fafcf9" stroke="#cfddd5"/>`;if(v.band)b+=`<rect x="${x(v.band[0])}" y="48" width="${Math.max(0,x(v.band[1])-x(v.band[0]))}" height="225" fill="#e8bc72" opacity=".16"/>`;
for(let i=0;i<=4;i++){let xx=loX+(hiX-loX)*i/4,yy=loY+(hiY-loY)*i/4;b+=`<path d="M${x(xx)} 48V273M75 ${y(yy)}H775" stroke="#e1e8e2"/><text x="${x(xx)}" y="296" text-anchor="middle" font-size="14">${xx.toFixed(hiX-loX<10?2:0)}</text><text x="65" y="${y(yy)+5}" text-anchor="end" font-size="14">${yy.toFixed(hiY-loY<10?2:0)}</text>`}
if(v.diagonal)b+=`<path d="M${x(loX)} ${y(loX)}L${x(hiX)} ${y(hiX)}" stroke="#9aa7ad" stroke-dasharray="5 4"/>`;
(v.truthMarkers||[]).forEach(a=>b+=`<path d="M${x(a)} 48V273" stroke="#929ca3" stroke-dasharray="3 5"/>`);(v.markers||[]).forEach(a=>b+=`<path d="M${x(a)} 48V273" stroke="#c07648" stroke-dasharray="7 4"/>`);
v.traces.forEach((t,j)=>{if(v.scatter||(v.scatterLast&&j===v.traces.length-1)){t.values.forEach(p=>{if(p[1]!==null)b+=`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="${v.scatterLast?6:3}" fill="${t.color}" opacity=".75"/>`})}else{let d='',started=false;t.values.forEach(p=>{if(p[1]===null){started=false;return}d+=(started?'L':'M')+x(p[0])+','+y(p[1]);started=true});b+=`<path d="${d}" fill="none" stroke="${t.color}" stroke-width="2.4"/>`}});b+=`<text x="420" y="338" text-anchor="middle" font-size="16">${esc(v.xLabel)}</text><text x="75" y="24" font-size="16">${esc(v.yLabel)}</text>`;return svg(v.title,b)}
function draw(){const r=state.results;$('metrics').innerHTML=r.metrics.map(m=>`<div class="metric"><span>${esc(m.label)}</span><strong>${esc(fmt(m.value))}</strong><small>${esc(m.unit)}</small></div>`).join('');$('plots').innerHTML=r.views.map(v=>`<article class="plot"><h3>${esc(v.title)}</h3>${chart(v)}${v.traces?'<div class="legend">'+v.traces.map(t=>`<span style="--color:${t.color}">${esc(t.name)}</span>`).join('')+'</div>':''}</article>`).join('');$('explanation').innerHTML=r.notes.map(t=>`<p>${esc(t)}</p>`).join('');$('training').textContent=JSON.stringify({split:r.split,training:r.training},null,2)}
function run(){try{state.params=params();state.results=E.run(state.params);state.status='ready';state.revision++;draw();drawReviews();$('save-review').disabled=false;$('status').textContent='计算完成：当前图表、模型、基线与评价使用同一组参数。';$('results').classList.remove('stale');$('export').disabled=false}catch(e){state.status='error';$('status').textContent='请检查输入：'+e.message;$('export').disabled=true;$('save-review').disabled=true;drawReviews();console.error(e)}}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{let tab=b.dataset.tab;['background','workflow','lab'].forEach(id=>$(id).hidden=id!==tab);document.querySelectorAll('[data-tab]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));try{history.replaceState(null,'','#'+tab)}catch(_){}}));
document.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{let out=$(el.id+'-out');if(out)out.textContent=el.value;state.status='stale';$('save-review').disabled=true;drawReviews();$('status').textContent='参数已改变；点击重新计算，更新图表与指标。';$('results').classList.add('stale');$('export').disabled=true}));$('run').addEventListener('click',run);$('reset').addEventListener('click',()=>{C.params.forEach(a=>{$(a[0]).value=a[5];$(a[0]+'-out').textContent=a[5]});(C.selects||[]).forEach(a=>$(a[0]).value=a[2][0][0]);run()});$('export').addEventListener('click',()=>{if(state.status!=='ready')return;let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({caseId:C.id,sceneId:C.scene,status:state.status,dataNature:'reproducible_teaching_fixture',reviewHistory:state.reviews,inputRevision:state.revision,...state.results},null,2)],{type:'application/json'}));a.href=u;a.download=C.id+'-calculation.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
function drawReviews(){$('review-history').innerHTML=state.reviews.map(v=>'<p><b>计算 '+v.revision+' · '+(v.revision===state.revision&&state.status==='ready'?'当前':'历史，当前参数未沿用')+'</b> '+esc(v.note)+'</p>').join('')||'<p>尚未记录人工依据。</p>'} $('save-review').addEventListener('click',()=>{if(state.status!=='ready')return;let note=$('review-note').value.trim();if(!note){$('review-note').focus();return}state.reviews.push({revision:state.revision,params:{...state.params},note});$('review-note').value='';drawReviews()});
g.CaseInspect={snapshot:()=>JSON.parse(JSON.stringify({sceneId:C.scene,caseId:C.id,status:state.status,params:params(),results:state.results?{metrics:state.results.metrics,split:state.results.split}:null,metrics:state.results?.metrics})),evidence:()=>state.status==='ready'?JSON.parse(JSON.stringify({...state.results,reviewHistory:state.reviews,inputRevision:state.revision})):null};let tab=location.hash.slice(1);if(['background','workflow','lab'].includes(tab))document.querySelector('[data-tab="'+tab+'"]').click();run();})(globalThis);